import 'bootstrap/dist/css/bootstrap.min.css';
import React, { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import ProfileForm from './components/ProfileForm';
import MatchCard from './components/MatchCard';
import Login from './components/Login'; 
import Register from './components/Register';
import ChatRoom from './components/ChatRoom'; 
import NavBar from './components/NavBar';
import { Container, Spinner } from 'react-bootstrap'; 
import Stats from './pages/Stats'; 

function App() {
    const [isLoggedIn, setIsLoggedIn] = useState(false); 
    const [isProfileSet, setIsProfileSet] = useState(false); 
    const [matchProfiles, setMatchProfiles] = useState([]);
    const [loading, setLoading] = useState(true);
    
    const [currentView, setCurrentView] = useState('match_list'); 
    const [activeRoomName, setActiveRoomName] = useState(null); 
    const [chatRooms, setChatRooms] = useState([]);

    // 로그아웃 처리
    const handleLogout = useCallback(() => {
        localStorage.removeItem('accessToken');
        setIsLoggedIn(false);
        setIsProfileSet(false);
        setMatchProfiles([]);
        setChatRooms([]);
        setCurrentView('login'); 
    }, []);

    // 📌 [핵심 수정] 프로필 존재 여부 확인 함수
    const checkProfileExistence = useCallback(async (token) => {
        try {
            const response = await axios.get(
                'http://127.0.0.1:8000/api/users/userprofile/me/', 
                { headers: { 'Authorization': `Bearer ${token}` } }
            );
            
            // 🚨 수정됨: 단순히 status 200인지만 보는 게 아니라, "닉네임"이 있는지 확인합니다.
            // 회원가입 때 사진만 넣고 닉네임이 비어있으면 isProfileComplete는 false가 됩니다.
            const userData = response.data;
            const isProfileComplete = userData && userData.nickname && userData.nickname.trim() !== '';

            setIsProfileSet(isProfileComplete);
            return isProfileComplete; // true면 메인으로, false면 프로필 입력창으로 감

        } catch (error) {
            // 404면 프로필 자체가 없는 것이므로 false
            if (error.response?.status === 404) {
                setIsProfileSet(false);
                return false;
            } 
            // 인증 실패 시 로그아웃
            else if (error.response?.status === 401) {
                handleLogout();
            }
            console.error("프로필 확인 중 오류 발생:", error);
            setIsProfileSet(false);
            return false;
        }
    }, [handleLogout]);

    // 매칭 대상 불러오기
    const fetchMatches = useCallback(async () => {
        const token = localStorage.getItem('accessToken');
        if (!token) return; 

        setLoading(true);
        try {
            const response = await axios.get(
                'http://127.0.0.1:8000/api/users/userprofile/matches/',
                { headers: { 'Authorization': `Bearer ${token}` } }
            );
            setMatchProfiles(response.data);
        } catch (error) {
            console.error("매칭 목록 불러오기 실패:", error);
            if (error.response?.status === 401) {
                handleLogout();
            }
        } finally {
            setLoading(false);
        }
    }, [handleLogout]);

    // 채팅방 목록 불러오기
    const fetchChatRooms = useCallback(async () => {
        const token = localStorage.getItem('accessToken');
        if (!token) return;

        setLoading(true);
        try {
            const response = await axios.get(
                'http://127.0.0.1:8000/api/chat/rooms/',
                { headers: { 'Authorization': `Bearer ${token}` } }
            );
            setChatRooms(response.data);
            setCurrentView('chat_list'); 
        } catch (error) {
            console.error("채팅방 목록 불러오기 실패:", error);
            if (error.response?.status === 401) {
                 handleLogout();
            }
        } finally {
            setLoading(false);
        }
    }, [handleLogout]);

    // 1. 앱 시작 시 체크
    useEffect(() => {
        const token = localStorage.getItem('accessToken'); 
        if (token) {
            setIsLoggedIn(true);
            checkProfileExistence(token).then((profileComplete) => {
                // 닉네임이 없으면(false) -> 프로필 폼으로 보냄
                if (!profileComplete) {
                    setCurrentView('profile_form');
                } else {
                    setCurrentView('match_list'); 
                }
            }).finally(() => {
                setLoading(false);
            });
        } else {
            setLoading(false);
            setCurrentView('login');
        }
    }, [checkProfileExistence]); 

    // 2. 데이터 로드 관리
    useEffect(() => {
        if (isLoggedIn && isProfileSet) {
            if (currentView === 'match_list') {
                fetchMatches();
            } else if (currentView === 'chat_list') {
                fetchChatRooms();
            } 
        }
    }, [isLoggedIn, isProfileSet, fetchMatches, fetchChatRooms, currentView]);

    // NavBar 네비게이션
    const navigateTo = useCallback((viewName) => {
        setCurrentView(viewName);
        if (viewName === 'match_list') {
            fetchMatches(); 
        } else if (viewName === 'chat_list') {
            fetchChatRooms(); 
        }
    }, [fetchMatches, fetchChatRooms]);

    // 📌 로그인 성공 처리 (Login.js에서 호출됨)
    const handleLoginSuccess = useCallback(async (token) => {
        localStorage.setItem('accessToken', token);
        setIsLoggedIn(true);
        
        // 로그인 직후 프로필(닉네임) 확인
        const isComplete = await checkProfileExistence(token);
        
        if (isComplete) {
            setCurrentView('match_list'); // 닉네임 있으면 메인
        } else {
            setCurrentView('profile_form'); // 닉네임 없으면 프로필 완성 페이지
        }
    }, [checkProfileExistence]);

    // 프로필 생성 완료 처리
    const handleProfileCreated = useCallback(() => {
        setIsProfileSet(true);
        navigateTo('match_list'); 
    }, [navigateTo]);
    
    const handleLikeSuccess = useCallback((likedUserId) => {
        setMatchProfiles(prevProfiles => prevProfiles.filter(p => p.user !== likedUserId));
    }, []);

    const handleMatchSuccess = useCallback((roomName) => {
        setActiveRoomName(roomName);
        setCurrentView('chat');
    }, []);

    const getCurrentUserId = () => {
        try {
            const token = localStorage.getItem('accessToken');
            if (token) {
                const payload = token.split('.')[1];
                const decodedPayload = JSON.parse(atob(payload));
                return decodedPayload.user_id; 
            }
        } catch (e) {
            console.error("JWT 파싱 실패:", e);
        }
        return null;
    };

    // --- 렌더링 ---
    if (loading) {
        return <div style={{ textAlign: 'center', padding: '50px' }}>앱 데이터를 로딩 중입니다...</div>;
    }
    
    // 1. 로그인/회원가입 화면 (NavBar 없음)
    if (currentView === 'login' || currentView === 'register' || !isLoggedIn) {
        if (currentView === 'register') {
            return <Register onRegisterSuccess={() => setCurrentView('login')} />;
        }
        return (
            <Login 
                onLoginSuccess={handleLoginSuccess} 
                onRegisterClick={() => setCurrentView('register')} 
            />
        );
    }
    
    // 2. 프로필 설정 화면 (닉네임 없을 때)
    if (currentView === 'profile_form' || (isLoggedIn && !isProfileSet)) {
        return <ProfileForm onProfileCreated={handleProfileCreated} />;
    }
    
    // 3. 메인 앱 화면 (NavBar 포함)
    let mainContent;
    
    if (currentView === 'chat' && activeRoomName) {
        mainContent = (
            <ChatRoom 
                roomName={activeRoomName} 
                onClose={() => navigateTo('chat_list')} 
            />
        );
    } else if (currentView === 'chat_list') {
        const currentUserId = getCurrentUserId();
        mainContent = (
            <div style={{ padding: '20px', maxWidth: '600px', margin: '0 auto', textAlign: 'left' }}>
                <h1 style={{ textAlign: 'center' }}>내 채팅 목록 💬</h1>
                {loading ? (
                    <p style={{ textAlign: 'center' }}><Spinner animation="border" size="sm" /> 로딩 중...</p>
                ) : chatRooms.length > 0 ? (
                    chatRooms.map(room => {
                        const targetNickname = (room.user1.toString() === currentUserId.toString()) 
                            ? room.user2_nickname 
                            : room.user1_nickname;
                        return (
                            <div key={room.id} onClick={() => handleMatchSuccess(room.name)} 
                                style={{ padding: '15px', borderBottom: '1px solid #eee', cursor: 'pointer', backgroundColor: '#fff', marginTop: '10px' }}>
                                <strong>{targetNickname}</strong> 님과의 대화
                            </div>
                        );
                    })
                ) : (
                    <p style={{ textAlign: 'center', marginTop: '30px' }}>채팅방이 없습니다.</p>
                )}
            </div>
        );
    } else if (currentView === 'stats') {
        mainContent = <Stats />;
    } else { 
        // match_list
        mainContent = (
            <div style={{ padding: '20px', textAlign: 'center' }}>
                <h1>오늘의 매칭 대상 ✨</h1>
                <div style={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'center' }}>
                    {matchProfiles.length > 0 ? (
                        matchProfiles.map(profile => (
                            <MatchCard 
                                key={profile.user} 
                                profile={profile} 
                                onLikeSuccess={handleLikeSuccess} 
                                onMatchSuccess={handleMatchSuccess}
                            />
                        ))
                    ) : (
                        <p style={{ marginTop: '20px' }}>매칭 가능한 프로필이 없습니다.</p>
                    )}
                </div>
            </div>
        );
    }

    return (
        <React.Fragment>
            <NavBar onNavigate={navigateTo} onLogout={handleLogout} currentView={currentView} />
            <Container className="mt-4">
                {mainContent}
            </Container>
        </React.Fragment>
    );
}

export default App;
